Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
When the SCTP ADD_OUT_STREAMS request is denied, the rollback only called `sctp_stream_shrink_out()`, which reduces `outcnt` and shrinks queued chunks but does not properly unschedule streams from the scheduler or clean up the stream extension (ext) metadata. This leaves stale scheduler state and freed ext pointers, so a subsequent re-add of the same stream slot can cause a null-pointer dereference in the scheduler get path when it tries to access the ext.

Here is the patch:

 struct sctp_chunk *sctp_process_strreset_resp(
 				struct sctp_association *asoc,
 				union sctp_params param,
 				struct sctp_ulpevent **evp)
 {
 	struct sctp_stream *stream = &asoc->stream;
 	struct sctp_strreset_resp *resp = param.v;
 	struct sctp_transport *t;
 	__u16 i, nums, flags = 0;
 	struct sctp_paramhdr *req;
 	__u32 result;

 	req = sctp_chunk_lookup_strreset_param(asoc, resp->response_seq, 0);
 	if (!req)
 		return NULL;

 	result = ntohl(resp->result);
 	if (result != SCTP_STRRESET_PERFORMED) {
 		/* if in progress, do nothing but retransmit */
 		if (result == SCTP_STRRESET_IN_PROGRESS)
 			return NULL;
 		else if (result == SCTP_STRRESET_DENIED)
 			flags = SCTP_STREAM_RESET_DENIED;
 		else
 			flags = SCTP_STREAM_RESET_FAILED;
 	}

 	if (req->type == SCTP_PARAM_RESET_OUT_REQUEST) {
 		struct sctp_strreset_outreq *outreq;
 		__be16 *str_p;

 		outreq = (struct sctp_strreset_outreq *)req;
 		str_p = outreq->list_of_streams;
 		nums = (ntohs(outreq->param_hdr.length) - sizeof(*outreq)) /
 		       sizeof(__u16);

 		if (result == SCTP_STRRESET_PERFORMED) {
 			struct sctp_stream_out *sout;
 			if (nums) {
 				for (i = 0; i < nums; i++) {
 					sout = SCTP_SO(stream, ntohs(str_p[i]));
 					sout->mid = 0;
 					sout->mid_uo = 0;
 				}
 			} else {
 				for (i = 0; i < stream->outcnt; i++) {
 					sout = SCTP_SO(stream, i);
 					sout->mid = 0;
 					sout->mid_uo = 0;
 				}
 			}
 		}

 		flags |= SCTP_STREAM_RESET_OUTGOING_SSN;

 		for (i = 0; i < stream->outcnt; i++)
 			SCTP_SO(stream, i)->state = SCTP_STREAM_OPEN;

 		*evp = sctp_ulpevent_make_stream_reset_event(asoc, flags,
 			nums, str_p, GFP_ATOMIC);
 	} else if (req->type == SCTP_PARAM_RESET_IN_REQUEST) {
 		struct sctp_strreset_inreq *inreq;
 		__be16 *str_p;

 		/* if the result is performed, it's impossible for inreq */
 		if (result == SCTP_STRRESET_PERFORMED)
 			return NULL;

 		inreq = (struct sctp_strreset_inreq *)req;
 		str_p = inreq->list_of_streams;
 		nums = (ntohs(inreq->param_hdr.length) - sizeof(*inreq)) /
 		       sizeof(__u16);

 		flags |= SCTP_STREAM_RESET_INCOMING_SSN;

 		*evp = sctp_ulpevent_make_stream_reset_event(asoc, flags,
 			nums, str_p, GFP_ATOMIC);
 	} else if (req->type == SCTP_PARAM_RESET_TSN_REQUEST) {
 		struct sctp_strreset_resptsn *resptsn;
 		__u32 stsn, rtsn;

 		/* check for resptsn, as sctp_verify_reconf didn't do it*/
 		if (ntohs(param.p->length) != sizeof(*resptsn))
 			return NULL;

 		resptsn = (struct sctp_strreset_resptsn *)resp;
 		stsn = ntohl(resptsn->senders_next_tsn);
 		rtsn = ntohl(resptsn->receivers_next_tsn);

 		if (result == SCTP_STRRESET_PERFORMED) {
 			__u32 mtsn = sctp_tsnmap_get_max_tsn_seen(
 						&asoc->peer.tsn_map);
 			LIST_HEAD(temp);

 			asoc->stream.si->report_ftsn(&asoc->ulpq, mtsn);

 			sctp_tsnmap_init(&asoc->peer.tsn_map,
 					 SCTP_TSN_MAP_INITIAL,
 					 stsn, GFP_ATOMIC);

 			/* Clean up sacked and abandoned queues only. As the
 			 * out_chunk_list may not be empty, splice it to temp,
 			 * then get it back after sctp_outq_free is done.
 			 */
 			list_splice_init(&asoc->outqueue.out_chunk_list, &temp);
 			sctp_outq_free(&asoc->outqueue);
 			list_splice_init(&temp, &asoc->outqueue.out_chunk_list);

 			asoc->next_tsn = rtsn;
 			asoc->ctsn_ack_point = asoc->next_tsn - 1;
 			asoc->adv_peer_ack_point = asoc->ctsn_ack_point;

 			for (i = 0; i < stream->outcnt; i++) {
 				SCTP_SO(stream, i)->mid = 0;
 				SCTP_SO(stream, i)->mid_uo = 0;
 			}
 			for (i = 0; i < stream->incnt; i++)
 				SCTP_SI(stream, i)->mid = 0;
 		}

 		for (i = 0; i < stream->outcnt; i++)
 			SCTP_SO(stream, i)->state = SCTP_STREAM_OPEN;

 		*evp = sctp_ulpevent_make_assoc_reset_event(asoc, flags,
 			stsn, rtsn, GFP_ATOMIC);
 	} else if (req->type == SCTP_PARAM_RESET_ADD_OUT_STREAMS) {
 		struct sctp_strreset_addstrm *addstrm;
+		const struct sctp_sched_ops *sched;
 		__u16 number;

 		addstrm = (struct sctp_strreset_addstrm *)req;
 		nums = ntohs(addstrm->number_of_streams);
 		number = stream->outcnt - nums;

 		if (result == SCTP_STRRESET_PERFORMED) {
 			for (i = number; i < stream->outcnt; i++)
 				SCTP_SO(stream, i)->state = SCTP_STREAM_OPEN;
 		} else {
-			sctp_stream_shrink_out(stream, number);
+			sched = sctp_sched_ops_from_stream(stream);
+			sched->unsched_all(stream);
+			sctp_stream_outq_migrate(stream, NULL, number);
+			sched->sched_all(stream);
 			stream->outcnt = number;
 		}

 		*evp = sctp_ulpevent_make_stream_change_event(asoc, flags,
 			0, nums, GFP_ATOMIC);
 	} else if (req->type == SCTP_PARAM_RESET_ADD_IN_STREAMS) {
 		struct sctp_strreset_addstrm *addstrm;

 		/* if the result is performed, it's impossible for addstrm in
 		 * request.
 		 */
 		if (result == SCTP_STRRESET_PERFORMED)
 			return NULL;

 		addstrm = (struct sctp_strreset_addstrm *)req;
 		nums = ntohs(addstrm->number_of_streams);

 		*evp = sctp_ulpevent_make_stream_change_event(asoc, flags,
 			nums, 0, GFP_ATOMIC);
 	}

 	asoc->strreset_outstanding--;
 	asoc->strreset_outseq++;

 	/* remove everything for this reconf request */
 	if (!asoc->strreset_outstanding) {
 		t = asoc->strreset_chunk->transport;
 		if (timer_delete(&t->reconf_timer))
 			sctp_transport_put(t);

 		sctp_chunk_put(asoc->strreset_chunk);
 		asoc->strreset_chunk = NULL;
 	}

 	return NULL;
 }
